sql.where:
l.deleted = 0

    AND (l.code ILIKE '%' || #{q.keyword} || '%'
         OR l.zone ILIKE '%' || #{q.keyword} || '%')


    AND l.status = #{q.status}


    AND l.warehouse_id = #{q.warehouseId}


    AND l.location_type = #{q.locationType}


    AND l.zone = #{q.zone}

mapper.select:
SELECT count(*)
FROM wms_location
WHERE warehouse_id = #{warehouseId}
  AND zone = #{zone}
  AND deleted = 0
